class barrier {                                  // pre-C++20 fallback
    std::mutex m;
    std::condition_variable cv;
    unsigned left, gen = 0;
    const unsigned parties;
public:
    explicit barrier(unsigned n) : left(n), parties(n) {}
    void wait() {
        std::unique_lock lk(m);
        auto g = gen;
        if (--left == 0) { gen++; left = parties; cv.notify_all(); }
        else cv.wait(lk, [&] { return gen != g; });   // predicate loop
    }
};
